function showPassword(e){const o=e.currentTarget.closest("button");o.innerHTML='<i class="bi bi-eye" onclick="hidePassword(event);"></i>';const r=o.parentNode.querySelector("input");r.type="text"}function hidePassword(e){const o=e.currentTarget.closest("button");o.innerHTML='<i class="bi bi-eye-slash" onclick="showPassword(event);"></i>';const r=o.parentNode.querySelector("input");r.type="password"}function login(e,o,r){console.log("login ajax");$.ajax({type:"POST",url:"login",data:{a:"login",email:e,password:o,page:r},success:function(e){$("#login-response").html(e)},error:function(e){$("#login-response").html(e.responseText)}})}function wrongPwd(e="#login-form",o="Sai mật khẩu"){const r=document.querySelector(e);const n=r.querySelector(".pwd-error");n.innerText=o;r.querySelector(".email-error").innerText=""}function wrongNewPwd(e,o){const r=document.querySelector(e);r.querySelector(".new-pwd-error").innerText=o;r.querySelector(".re-new-pwd-error").innerText=o}function existedEmail(e,o){clearError(e);const r=document.querySelector(e);r.querySelector(".email-error").innerText=o}function clearForm(e){const o=document.querySelector(e);const r=o.querySelectorAll("input");r.forEach((e=>{e.value=""}));const n=o.querySelectorAll(".form-error");n.forEach((e=>{e.innerText=""}))}function clearError(e){const o=document.querySelector(e);const r=o.querySelectorAll(".form-error");r.forEach((e=>{e.innerText=""}))}function unexistedEmail(){const e=document.querySelector("#login-form .email-error");e.innerText="Email chưa được đăng ký!";document.querySelector('#login-form input[name="password"]').value="";document.querySelector("#login-form .pwd-error").innerText=""}function forward(e){window.location.href=e}function signup(e,o,r,n){const t=/^(?=.*[a-z]).{8,}$/;if(!t.test(r)){clearError("#signup-form");wrongNewPwd("#signup-form","* Mật khẩu phải ít nhất 8 ký tự")}else if(r!=n){clearError("#signup-form");wrongNewPwd("#signup-form","Mật khẩu không trùng khớp")}else{$.ajax({url:"signup",method:"POST",data:{a:"signup",name:e,email:o,password:r,repassword:n},success:function(e){$("#signup-response").html(e)}})}}function openModal2(e){const o=document.querySelector(e);o.classList.add("active")}function closeModal(e){const o=document.querySelector(e);o.classList.remove("active")}function forgetPwd(e){e.preventDefault();openModal2(".forger-pwd-modal")}document.addEventListener("DOMContentLoaded",(function(){if(document.querySelector("#login-form")){document.querySelector("#login-form").addEventListener("submit",(function(e){e.preventDefault();console.log("form submit");var o=new FormData(this);var r=o.get("email");var n=o.get("password");var t=o.get("page");$.ajax({type:"POST",url:"login",data:{a:"login",email:r,password:n,page:t},success:function(e){$("#login-response").html(e)},error:function(e){$("#login-response").html(e.responseText)}})}))}if(document.querySelector("#signup-form")){document.querySelector("#signup-form").addEventListener("submit",(function(e){e.preventDefault();console.log("signup form submit");var o=new FormData(document.querySelector("#signup-form"));var r=o.get("name");var n=o.get("email");var t=o.get("password");var c=o.get("repassword");document.querySelector('#verifyAccountForm input[name="email"]').value=n;signup(r,n,t,c)}))}}));function submitVerifyAccountForm(){document.querySelector("#btn-to-verify-account").click()}